package ai.taskforge.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="documents") public class Document { @Id @GeneratedValue private UUID id; @Column(nullable=false) private String filename; @Column(nullable=false) private String contentType; @Column(nullable=false) private String status="INDEXED"; @Column(length=200000) private String extractedText; @ManyToOne @JoinColumn(name="uploaded_by_id") private AppUser uploadedBy; private Instant uploadedAt=Instant.now(); protected Document(){} public Document(String n,String ct,String text,AppUser u){filename=n;contentType=ct;extractedText=text;uploadedBy=u;} public UUID getId(){return id;} public String getFilename(){return filename;} public String getContentType(){return contentType;} public String getExtractedText(){return extractedText;} public String getStatus(){return status;} public Instant getUploadedAt(){return uploadedAt;} }
